ALIASES = {"primarySiteCode": "primarySite", "gradeCode": "grade", "lateralityCode": "laterality", "birthDate": "dateOfBirth", "patientLastName": "nameLast", "patientFirstName": "nameFirst", "hispanicOriginCode": "spanishHispanicOrigin", "vitalStatusCode": "vitalStatus", "progesteroneReceptorSummary": "progesteroneRecepSummary", "radiationTherapyCode": "rxSummRadiation", "chemotherapyCode": "rxSummChemo", "surgeryPrimarySiteCode": "rxSummSurgPrimSite2023", "hormoneTherapyCode": "rxSummHormone", "dateOfLastContactCode": "dateOfLastContact"}
CAT="serverless_stable_omnigent_catalog"; SCH="cancer_gold"

OFF_LC = {k.lower():(k,v) for k,v in OFFICIAL.items()}
def norm(n):
    n=n.lower()
    for suf in ("code","number","flag","id","summary"):
        if n.endswith(suf) and len(n)>len(suf)+2: n=n[:-len(suf)]
    return n
OFF_NORM={}
for k,v in OFFICIAL.items():
    OFF_NORM.setdefault(norm(k),(k,v))

def resolve(name):
    if name in ALIASES and ALIASES[name] in OFFICIAL:
        t=ALIASES[name]; return t, OFFICIAL[t], "alias"
    if name.lower() in OFF_LC:
        k,v=OFF_LC[name.lower()]; return k,v,"exact"
    nn=norm(name)
    if nn in OFF_NORM:
        k,v=OFF_NORM[nn]; return k,v,"normalized"
    return None,None,"unmapped"

def main():
    spark=SparkSession.builder.getOrCreate()
    rows=spark.sql(f"SELECT * FROM {CAT}.{SCH}.gold_naaccr_dictionary").collect()
    out=[]; mapped=0; unmapped=[]; how={"alias":0,"exact":0,"normalized":0,"unmapped":0}
    seen={}
    for r in rows:
        d=r.asDict()
        oid=d["naaccr_item_id"]; nm=d["item_name"]
        offid,offnum,method=resolve(nm)
        how[method]+=1
        if method=="unmapped":
            unmapped.append((oid,nm,d["section"])); newid=oid; newname=nm
        else:
            mapped+=1; newid=offnum; newname=offid
        seen.setdefault(newid,[]).append(nm)
        out.append(Row(naaccr_item_id=int(newid), old_naaccr_item_id=int(oid), item_name=newname,
            section=d["section"], data_type=d.get("data_type"), length=d.get("length"),
            required=d.get("required"), valid_values=d.get("valid_values"), unknown_code=d.get("unknown_code"),
            description=d.get("description"), code_system=d.get("code_system"),
            coding_instructions=d.get("coding_instructions"), reference_url=d.get("reference_url"),
            source=d.get("source"), version="NAACCR v25 (naaccr-dictionary-250)", map_method=method))
    dups={k:v for k,v in seen.items() if len(v)>1}
    spark.createDataFrame(out).write.mode("overwrite").option("overwriteSchema","true").saveAsTable(f"{CAT}.{SCH}.gold_naaccr_dictionary_v2")
    print("TOTAL", len(rows), "| MAPPED", mapped, "| UNMAPPED", len(unmapped))
    print("BY METHOD", how)
    print("DUPLICATE new ids (collisions):", len(dups))
    for k,v in list(dups.items())[:20]: print("  dup", k, v)
    print("UNMAPPED items:")
    for oid,nm,sec in unmapped: print(f"  {oid} {nm} [{sec}]")

if __name__=="__main__": main()
